using System;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEngine.Rendering;
public static class OptimizeMudScan {
struct Sum{public Vector3 p;public int n;}
public static string Main(){if(Application.isPlaying)throw new Exception("Stop Play before optimizing derived mesh assets");string report="";foreach(string token in new[]{"main0 6","main1 4"}){string path="Assets/Game/Generated/DeformableMud/Mud "+token+" forest-puddle.asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);var vertices=old.vertices;var uv=old.uv;var cells=new Vector3Int[vertices.Length];var sums=new Dictionary<Vector3Int,Sum>();for(int i=0;i<vertices.Length;i++){var key=new Vector3Int(Mathf.RoundToInt(vertices[i].x/.065f),Mathf.RoundToInt(vertices[i].y/.035f),Mathf.RoundToInt(vertices[i].z/.065f));cells[i]=key;sums.TryGetValue(key,out var sum);sum.p+=vertices[i];sum.n++;sums[key]=sum;}
var p=new List<Vector3>();var tex=new List<Vector2>();var uvSums=new List<Vector2>();var counts=new List<int>();var ids=new Dictionary<(Vector3Int,int,Vector2Int),int>();var triangles=new List<int>[old.subMeshCount];for(int sub=0;sub<triangles.Length;sub++){triangles[sub]=new List<int>();var map=new Dictionary<int,int>();var original=old.GetTriangles(sub);foreach(int i in original){if(map.ContainsKey(i))continue;var key=(cells[i],sub,Vector2Int.RoundToInt(uv[i]*16));if(!ids.TryGetValue(key,out int index)){index=p.Count;ids[key]=index;var sum=sums[cells[i]];p.Add(sum.p/sum.n);uvSums.Add(Vector2.zero);counts.Add(0);tex.Add(Vector2.zero);}map[i]=index;uvSums[index]+=uv[i];counts[index]++;}var unique=new HashSet<(int,int,int)>();for(int i=0;i<original.Length;i+=3){int a=map[original[i]],b=map[original[i+1]],c=map[original[i+2]];if(a==b||b==c||c==a||Vector3.Cross(p[b]-p[a],p[c]-p[a]).sqrMagnitude<1e-10f)continue;if(!unique.Add((a,b,c)))continue;triangles[sub].AddRange(new[]{a,b,c});}}
for(int i=0;i<tex.Count;i++)tex[i]=uvSums[i]/Mathf.Max(1,counts[i]);var mesh=new Mesh{name=old.name,indexFormat=IndexFormat.UInt32};mesh.SetVertices(p);mesh.SetUVs(0,tex);mesh.subMeshCount=triangles.Length;for(int i=0;i<triangles.Length;i++)mesh.SetTriangles(triangles[i],i);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();int before=old.vertexCount;Undo.RecordObject(old,"Optimize derived mud scan");EditorUtility.CopySerialized(mesh,old);EditorUtility.SetDirty(old);UnityEngine.Object.DestroyImmediate(mesh);string colliderPath="Assets/Game/Generated/DeformableMud/Mud collision "+token+" forest-puddle.asset";var collision=AssetDatabase.LoadAssetAtPath<Mesh>(colliderPath);var physical=UnityEngine.Object.Instantiate(old);var t=old.triangles;var both=new List<int>(t);for(int i=0;i<t.Length;i+=3)both.AddRange(new[]{t[i],t[i+2],t[i+1]});physical.subMeshCount=1;physical.SetTriangles(both,0);EditorUtility.CopySerialized(physical,collision);EditorUtility.SetDirty(collision);UnityEngine.Object.DestroyImmediate(physical);report+=token+": "+before+" -> "+old.vertexCount+" vertices; ";}AssetDatabase.SaveAssets();return report;}}
